import re
import json
from typing import List, Dict
from dialogue_graph import Graph, Node, Edge


def parse_script(text: str):
    """Parse script text into a dialogue graph dict."""
    graph = Graph()
    current_id = None
    current_lines: List[str] = []

    def flush_section():
        nonlocal current_id, current_lines
        if current_id is None:
            return
        # Clean lines
        lines = [ln.strip() for ln in current_lines if ln.strip()]
        if not lines:
            # empty node
            graph.add_node(Node(id=current_id, type="line"))
            current_id = None
            current_lines = []
            return

        # Identify choice lines
        choice_pattern = re.compile(r'^(\d+)\.\s*(.*?)\s*->\s*([A-Za-z0-9_]+)\s*$')
        choice_lines = []
        non_choice_exists = False
        for ln in lines:
            m = choice_pattern.match(ln)
            if m:
                choice_lines.append((m.group(2).strip(), m.group(3).strip()))
            else:
                non_choice_exists = True

        if choice_lines and not non_choice_exists:
            # Choice node
            graph.add_node(Node(id=current_id, type="choice"))
            for choice_text, target in choice_lines:
                graph.add_edge(Edge(source=current_id, target=target, text=choice_text))
        else:
            # Line node - parse first line
            line = lines[0]
            m = re.match(r'^(?:(.+?):\s*)?(.*?)\s*->\s*([A-Za-z0-9_]+)\s*$', line)
            if m:
                speaker = (m.group(1) or "").strip()
                text_line = (m.group(2) or "").strip()
                target = (m.group(3) or "").strip()
                graph.add_node(Node(id=current_id, speaker=speaker, text=text_line, type="line"))
                graph.add_edge(Edge(source=current_id, target=target))
            else:
                graph.add_node(Node(id=current_id, speaker="", text=line, type="line"))
        current_id = None
        current_lines = []

    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        section_match = re.match(r'^\[(.+?)\]\s*$', line)
        if section_match:
            # flush previous
            flush_section()
            current_id = section_match.group(1).strip()
            current_lines = []
        else:
            # line content
            if current_id is None:
                # ignore stray lines before first section
                continue
            current_lines.append(raw)

    # flush last
    flush_section()

    # Ensure End node exists if referenced or not
    if "End" not in graph.nodes:
        graph.add_node(Node(id="End", text="", speaker="", type="line"))

    return graph.to_dict()


def graph_to_dot(data: Dict) -> str:
    # Build dot string from dict
    def esc(s: str) -> str:
        return s.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n')

    lines = ["digraph Dialogue {", "  rankdir=TB;"]
    # nodes
    for node in data.get("nodes", []):
        node_id = node["id"]
        if node.get("type") == "choice":
            lines.append(f"  \"{esc(node_id)}\" [shape=diamond,label=\"{esc(node_id)}\"];")
        else:
            label = node_id
            speaker = node.get("speaker", "")
            text = node.get("text", "")
            if speaker or text:
                label = f"{node_id}\\n{speaker + ': ' if speaker else ''}{text}".rstrip()
            lines.append(f"  \"{esc(node_id)}\" [shape=box,label=\"{esc(label)}\"];")
    if not any(n.get("id") == "End" for n in data.get("nodes", [])):
        lines.append('  "End" [shape=doublecircle,label="End"];')
    # edges
    for edge in data.get("edges", []):
        src = edge["from"]
        tgt = edge["to"]
        text = edge.get("text", "")
        if text:
            lines.append(f"  \"{esc(src)}\" -> \"{esc(tgt)}\" [label=\"{esc(text)}\"];\n")
        else:
            lines.append(f"  \"{esc(src)}\" -> \"{esc(tgt)}\";")
    lines.append("}")
    return "\n".join(lines)


if __name__ == "__main__":
    with open('/app/script.txt', 'r', encoding='utf-8') as f:
        text = f.read()
    data = parse_script(text)
    # write json
    with open('/app/dialogue.json', 'w', encoding='utf-8') as f:
        json.dump(data, f, indent=2)
    # write dot
    dot = graph_to_dot(data)
    with open('/app/dialogue.dot', 'w', encoding='utf-8') as f:
        f.write(dot)
